mapper.select:
/*selectStkSearchList*/ SELECT * FROM ( SELECT A.*, ROWNUM AS rnum FROM ( SELECT STK_CD AS stkCd, STK_NM AS stkNm, STK_NM_EN AS stkNmEn, MKT_CD AS mktCd, STK_STATUS AS stkStatus, STK_TYPE AS stkType, SCRT_GRP_CLS_CD AS scrtGrpClsCd, INDEX_CD AS indexCd, SECTOR_CD AS sectorCd, MKT_CAP_SIZE AS mktCapSize, CURRENCY AS currency, LIST_DT AS listDt, SYMBOL AS symbol, NATN_CD AS natnCd, EXCH_CD AS exchCd, DOW30_YN AS dow30Yn, NAS100_YN AS nas100Yn, SNP500_YN AS snp500Yn, KOSPI200_SECT_CD AS kospi200SectCd, KOSPI100_YN AS kospi100Yn, KOSPI50_YN AS kospi50Yn, KOSDAQ150_YN AS kosdaq150Yn, MANG_YN AS mangYn, SLTR_YN AS sltrYn, USE_YN AS useYn, TO_NUMBER(PRDY_AVLS_SCAL) AS prdyAvlsScal, TO_NUMBER(BSOP_PRFI) AS bsopPrfi, TO_NUMBER(THTR_NTIN) AS thtrNtin, TO_NUMBER(ROE_VAL) AS roeVal, BASE_DT AS baseDt, COUNT(*) OVER() AS totalCount FROM TB_STK_MASTER WHERE STK_STATUS != 'DELIST'
AND MKT_CD IN ('KOSPI', 'KOSDAQ')
AND MKT_CD = #{in_mkt_cd}
AND KOSPI200_SECT_CD IS NOT NULL AND KOSPI100_YN = 'Y' AND KOSPI50_YN = 'Y' AND KOSDAQ150_YN = 'Y' AND KRX300_YN = 'Y'
AND MKT_CD IN ('NASDAQ', 'NYSE')
AND MKT_CD = #{in_mkt_cd}
AND SNP500_YN = 'Y' AND DOW30_YN = 'Y' AND NAS100_YN = 'Y'
AND (STK_TYPE = #{in_stk_type} OR SCRT_GRP_CLS_CD = #{in_stk_type})
AND (UPPER(STK_CD) LIKE UPPER('%' || #{in_keyword} || '%') OR UPPER(STK_NM) LIKE UPPER('%' || #{in_keyword} || '%') OR UPPER(STK_NM_EN) LIKE UPPER('%' || #{in_keyword} || '%') OR UPPER(SYMBOL) LIKE UPPER('%' || #{in_keyword} || '%'))
ORDER BY
PRDY_AVLS_SCAL DESC NULLS LAST TO_NUMBER(BSOP_PRFI) DESC NULLS LAST TO_NUMBER(THTR_NTIN) DESC NULLS LAST TO_NUMBER(ROE_VAL) DESC NULLS LAST STK_CD ASC
) A ) WHERE RNUM <= ${totalPagesize} AND RNUM > ${currentPageSize}
